{"content": "from flask import Flask, jsonify, request
from flask_cors import CORS

app = Flask(__name__)
CORS(app) # Enable CORS for frontend development

# Mock restaurant data
RESTAURANTS = [
    {"id": 1, "name": "The Italian Place", "cuisine": "Italian", "rating": 4.5},
    {"id": 2, "name": "Spicy Wok", "cuisine": "Chinese", "rating": 4.2},
    {"id": 3, "name": "Burger Heaven", "cuisine": "American", "rating": 4.8},
    {"id": 4, "name": "Taco Town", "cuisine": "Mexican", "rating": 4.0},
]

# Simple in-memory favorites storage (for MVP demonstration)
favorites = set()

@app.route('/search', methods=['GET'])
def search_restaurants():
    query = request.args.get('q', '').lower()

    if not query:
        return jsonify(RESTAURANTS)

    results = [
        r for r in RESTAURANTS 
        if query in r['name'].lower() or query in r['cuisine'].lower()
    ]
    return jsonify(results)

@app.route('/favorites', methods=['GET'])
def get_favorites():
    favorite_restaurants = [r for r in RESTAURANTS if r['id'] in favorites]
    return jsonify(favorite_restaurants)

@app.route('/favorites/<int:restaurant_id>', methods=['POST', 'DELETE'])
def toggle_favorite(restaurant_id):
    if restaurant_id not in [r['id'] for r in RESTAURANTS]:
        return jsonify({"error": "Restaurant not found"}), 404

    if request.method == 'POST':
        favorites.add(restaurant_id)
        return jsonify({"message": f"Restaurant {restaurant_id} added to favorites"}), 200
    elif request.method == 'DELETE':
        if restaurant_id in favorites:
            favorites.remove(restaurant_id)
            return jsonify({"message": f"Restaurant {restaurant_id} removed from favorites"}), 200
        else:
            return jsonify({"message": f"Restaurant {restaurant_id} was not in favorites"}), 400

if __name__ == '__main__':
    # Run on 0.0.0.0 to be accessible if containerized, port 5000 is standard
    app.run(debug=True, host='0.0.0.0', port=5000)", "path": "FoodSearchMVP_Web_Simple/backend/app.py"}

