                        } else { // For favorites list, we just render them
                            renderRestaurant(item, listElement, true);
                        }
                    });
                } else if (data.message) {
                    // Handle success messages from POST/DELETE
                    console.log(data.message);
                    loadFavorites(); // Refresh favorites list
                }
            } catch (error) {
                console.error(`Error fetching ${endpoint}:`, error);
                listElement.innerHTML = \`<p style="color: red;">Could not connect to backend at \${BACKEND_URL}. Is the server running?</p>\`;
            }
        }

        async function searchRestaurants() {
            const query = document.getElementById('searchInput').value;
            await fetchAndRender(\`search?q=\${encodeURIComponent(query)}\`, 'resultsList');
        }

        async function loadFavorites() {
            await fetchAndRender('favorites', 'favoritesList');
        }

        async function toggleFavorite(id, event) {
            event.stopPropagation(); // Prevent any potential list item click event

            const isCurrentlyFavorite = getFavoriteIds().includes(id);
            const method = isCurrentlyFavorite ? 'DELETE' : 'POST';

            try {
                const response = await fetch(\`\${BACKEND_URL}/favorites/\${id}\`, {
                    method: method,
                    headers: {
                        'Content-Type': 'application/json'
                    }
                });

                if (response.ok) {
                    // Re-fetch both lists to update state
                    await loadFavorites();
                    await searchRestaurants(); // Re-run search to update favorite button state on search results
                } else {
                    const errorData = await response.json();
                    alert(\`Failed to toggle favorite: \${errorData.error || response.statusText}\`);
                }
            } catch (error) {
                console.error('Error toggling favorite:', error);
                alert('Could not reach the backend to update favorites.');
            }
        }

        // --- Initialization ---
        document.addEventListener('DOMContentLoaded', () => {
            loadFavorites(); // Load favorites on page load
            searchRestaurants(); // Load all restaurants on page load
        });
